#include <stdio.h>
int main() {
    int n; if (scanf("%d", &n) != 1) return 0;
    long long a[100005];
    for (int i = 0; i < n; i++) scanf("%lld", &a[i]);
    long long k; scanf("%lld", &k);
    int first = 1;
    for (int i = 0; i < n; i++) {
        if (a[i] < k) {
            if (!first) putchar(' ');
            printf("%lld", a[i]); first = 0;
        }
    }
    putchar('\n');
    return 0;
}

code.C++:
#include <iostream>
#include <vector>
using namespace std;
int main() {
    int n; if (!(cin >> n)) return 0;
    vector<long long> a(n);
    for (int i = 0; i < n; i++) cin >> a[i];
    long long k; cin >> k;
    bool first = true;
    for (long long x : a) {
        if (x < k) {
            if (!first) cout << " ";
            cout << x; first = false;
        }
    }
    cout << "\n";
    return 0;
}

code.Java:
import java.util.Scanner;
public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        if (sc.hasNextInt()) {
            int n = sc.nextInt();
            long[] a = new long[n];
            for (int i = 0; i < n; i++) a[i] = sc.nextLong();
            long k = sc.nextLong();
            StringBuilder sb = new StringBuilder();
            for (long x : a) {
                if (x < k) {
                    if (sb.length() > 0) sb.append(" ");
                    sb.append(x);
                }
            }
            System.out.println(sb.toString());
        }
    }
}

