const fs = require("fs");
function main() {
    const toks = fs.readFileSync(0, "utf-8").trim().split(/\s+/);
    if (!toks || toks.length === 0 || toks[0] === "") return;
    const n = parseInt(toks[0], 10);
    const k = BigInt(toks[n + 1]);
    const res = [];
    for (let i = 1; i <= n; i++) if (BigInt(toks[i]) < k) res.push(toks[i]);
    console.log(res.join(" "));
}
main();

